package com.delivery.platform.payments.infrastructure;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import static org.assertj.core.api.Assertions.*;class SimulatedPaymentProviderTest{private final SimulatedPaymentProvider provider=new SimulatedPaymentProvider();@Test void approvesNormalReference(){assertThat(provider.process("APPROVE",BigDecimal.TEN,"PEN").approved()).isTrue();}@Test void rejectsDeclineReference(){assertThat(provider.process("DECLINE",BigDecimal.TEN,"PEN").approved()).isFalse();}}
